ww.greensheet.com/newswire&newswire_id=64328 (confidence high)."}, {"name": "Linda Jeng", "role": "Chief Legal & Policy Officer (founder, Digital Self Labs)", "company": "Aave Labs", "segment": "E", "region": "Washington DC, US", "stage": "Target", "warmth": "cold", "next_action": "Comment on two of their posts on different days, then send the note", "next_date": "2026-11-19", "linkedin": "", "why": "Former Fed, Treasury, SEC and OCC official; regular stablecoin-policy voice on panels and podcasts", "notes": "Source: https://consensus.coindesk.com/agenda/speaker/-linda-jeng (confidence medium)."}, {"name": "Sam Boboev", "role": "Founder & Writer", "company": "Fintech Wrap Up", "segment": "E", "region": "Not stated", "stage": "Target", "warmth": "cold", "next_action": "Comment on two of their posts on different days, then send the note", "next_date": "2026-11-19", "linkedin": "", "why": "Newsletter publishing 2026 reports on stablecoin startup opportunities, non-USD stablecoins and tokenization", "notes": "Source: https://www.pulse.bot/fintech/blogs/reports-five-startup-opportunities-in-stablecoins-the-next-age-of-fintech-asset-tokenization-in-fina-a3aa60aa-c018-4b99-85f6-135d38f969f9/ (confidence medium)."}, {"name": "Jason Mikula", "role": "Publisher", "company": "Fintech Business Weekly", "segment": "E", "region": "United States", "stage": "Target", "warmth": "cold", "next_action": "Comment on two of their posts on different days, then send the note", "next_date": "2026-11-20", "linkedin": "", "why": "Covers stablecoin market structure, BaaS risk and crypto legislation weekly; 2026 predictions episode on Fintech Takes", "notes": "Source: https://podwise.ai/episodes/6732272 (confidence high)."}, {"name": "Alex Johnson", "role": "Host & Writer", "company": "Fintech Takes", "segment": "E", "region": "United States", "stage": "Target", "warmth": "cold", "next_action": "Comment on two of their posts on different days, then send the note", "next_date": "2026-11-20", "linkedin": "", "why": "Widely read fintech newsletter and podcast; Jan 2026 episode set stablecoin market structure as a 2026 theme", "notes": "Source: https://podwise.ai/episodes/6732272 (confidence medium)."}], "po": [{"title": "What a payment company has to connect before stablecoin payouts go live", "format": "Article", "publish_date": "2026-11-10", "status": "Idea", "topic": "Stablecoin operations", "resource": "Stablecoin payments operating checklist"}, {"title": "The stablecoin payments operating checklist, on one page", "format": "Image", "publish_date": "2026-11-12", "status": "Idea", "topic": "Stablecoin operations", "resource": "Stablecoin payments operating checklist"}, {"title": "Where a stablecoin payment actually breaks: the five handoffs", "format": "Video", "publish_date": "2026-11-13", "status": "Idea", "topic": "Stablecoin operations", "resource": ""}, {"title": "Deposit tokens or stablecoins: how a regional bank should decide", "format": "Article", "publish_date": "2026-11-17", "status": "Idea", "topic": "Deposit tokens", "resource": "Load, Reach and Retention decision map"}, {"title": "Load, Reach and Retention: the one-page decision map for banks", "format": "Image", "publish_date": "2026-11-19", "status": "Idea", "topic": "Deposit tokens", "resource": "Load, Reach and Retention decision map"}, {"title": "Your charter decides your stablecoin regulator", "format": "Video", "publish_date": "2026-11-20", "status": "Idea", "topic": "Regulation", "resource": ""}, {"title": "How GCC institutions should read the stablecoin rulebooks before they build", "format": "Article", "publish_date": "2026-11-24", "status": "Idea", "topic": "MENA regulation", "resource": "GCC stablecoin rules at a glance"}, {"title": "Freeze and return: eight questions to ask your stablecoin issuer", "format": "Image", "publish_date": "2026-11-26", "status": "Idea", "topic": "Freeze governance", "resource": "Freeze-and-return due diligence questions"}, {"title": "The freeze worked. Who gets the money back?", "format": "Video", "publish_date": "2026-11-27", "status": "Idea", "topic": "Freeze governance", "resource": ""}, {"title": "What a bank has to control before an AI agent can pay", "format": "Article", "publish_date": "2026-12-01", "status": "Idea", "topic": "Agent payments", "resource": "Agent payment controls checklist"}, {"title": "Agent payment controls: the checklist a risk team will ask for", "format": "Image", "publish_date": "2026-12-03", "status": "Idea", "topic": "Agent payments", "resource": "Agent payment controls checklist"}, {"title": "Into Lagos and Nairobi: why the off-ramp decides the corridor", "format": "Video", "publish_date": "2026-12-04", "status": "Idea", "topic": "Africa cross-border", "resource": ""}], "t": [{"name": "Connection note: value then question", "kind": "note", "body": "[First name], on [their stated interest or recent post]: [one verified fact they probably have not seen], so [one-clause consequence for their job]. [One specific question answerable from judgement]?", "sort": 1}, {"name": "First message after they accept", "kind": "message", "body": "Thanks for connecting, [First name]. Following on from [topic of the comment or note]: [the next layer of the same point, one or two sentences, one sourced fact]. In your experience, [one question about how their team handles it]?", "sort": 2}, {"name": "Resource reply (Thursday post)", "kind": "message", "body": "[First name], here is the [resource name] I mentioned. It is a one-page view of [what it covers]. Page [n] is the part most [their role] teams ask about first. Happy to hear which item looks hardest from where you sit.", "sort": 3}, {"name": "Call offer (conversation running)", "kind": "message", "body": "[First name], this is a useful thread. If it helps, I can take 20 minutes to walk through how we would approach [their specific problem] for a [their institution type]. Does [two specific slots] work on your side?", "sort": 4}, {"name": "Thursday comment prompt: variant A", "kind": "post", "body": "If you want the one-page [resource name], comment '[keyword]' and I will send it over today.", "sort": 5}, {"name": "Thursday comment prompt: variant B", "kind": "post", "body": "I put the full checklist on one page. Tell me in the comments which item your team finds hardest, and I will send you the page.", "sort": 6}, {"name": "Reply to a comment on Shashi's post", "kind": "reply", "body": "Thank you, [First name]. [Build on their strongest point in one sentence]. [Add one thing they did not mention]. From what you see in [their market or role], [one question]?", "sort": 7}, {"name": "InMail (top-tier, after two comments)", "kind": "inmail", "body": "Subject: [specific topic from their post]\n\n[First name], after your post on [topic], one point that may be useful: [verified fact plus consequence, two sentences]. I put together a one-page [resource] on it. Would it be useful if I sent it across?", "sort": 8}], "q": [{"question": "Who builds stablecoin payment infrastructure for banks in the UAE?", "topic": "Stablecoin payments", "region": "UAE", "sort": 1}, {"question": "How should a payment company reconcile stablecoin payouts with its general ledger?", "topic": "Stablecoin operations", "region": "Global", "sort": 2}, {"question": "Deposit tokens or stablecoins: which should a US regional bank choose?", "topic": "Deposit tokens", "region": "US", "sort": 3}, {"question": "What does a bank need in place before offering stablecoin payments from GIFT City?", "topic": "Stablecoin payments", "region": "India", "sort": 4}, {"question": "Which companies build tokenisation platforms for real estate funds in Dubai?", "topic": "Tokenisation", "region": "UAE", "sort": 5}, {"question": "How do stablecoin issuers decide when to freeze funds and how are they returned?", "topic": "Freeze governance", "region": "Global", "sort": 6}, {"question": "What controls does a bank need before letting an AI agent make payments?", "topic": "Agent payments", "region": "Global", "sort": 7}, {"question": "Who builds RWA tokenisation platforms for asset managers in Saudi Arabia?", "topic": "Tokenisation", "region": "Saudi Arabia", "sort": 8}, {"question": "How can a fintech launch stablecoin remittances into Nigeria or Kenya compliantly?", "topic": "Cross-border payments", "region": "Africa", "sort": 9}, {"question": "What does the OCC final rule under the GENIUS Act require on stablecoin redemption?", "topic": "Regulation", "region": "US", "sort": 10}], "s": [{"kind": "strategy", "title": "Goal for the month", "body": "Turn Shashi's LinkedIn presence into conversations and calls with the right institutions.\n\nResults, in order: attraction (reach, followers), engagement (replies, conversations started), AI citations (ChatGPT, Perplexity, Gemini, Claude naming Shashi or Antier), then calls booked.\n\nExpected month (see Results for all three scenarios): about 96 accepted connections, about 25 conversations, about 60 resource requests, about 6 calls, about 18,000 impressions.", "sort": 1}, {"kind": "strategy", "title": "Who we target", "body": "A · Fintech, payments and stablecoin operators (US, UK, UAE): 35% of effort\nB · Banks, asset managers, fund admins, custodians, payment providers in MENA and India, VP and above: 25%\nC · Partnerships and growth leads (CBO, CRO, BD, partnerships) at payments, custody, tokenisation and infrastructure firms: 20%\nD · Africa (Lagos, Nairobi, Johannesburg, Cape Town, Cairo, Casablanca, Kigali, Accra, Mauritius): 10%\nE · Industry voices, for reach only: 10%\n\nVP-level people are the easiest first conversation. Use them as the entry point to an account and reach C-level through the thread over time.\n\nSkip: tier-1 global banks as buyers, Big 4 as buyers, regulators (never message), traders and retail.", "sort": 2}, {"kind": "strategy", "title": "Content system: three posts a week", "body": "Tuesday · Long-form LinkedIn article, built to be cited by AI tools: a buyer question as the title, H2 headings, numbered lists, named regulators and institutions, every number sourced.\nThursday · Short text plus one image, with a comment prompt for that week's free resource. Vary the prompt wording each week so it does not read as the same bait.\nFriday · Motion-graphics video (Kanishk.Rewires studio). Shashi does not appear on camera.\n\nEvery post: reply to every comment within 90 minutes, send the resource by DM the same day to anyone who asks.", "sort": 3}, {"kind": "strategy", "title": "Commenting rules", "body": "8 comments a day from week 2 (6 in week 1), about 60% on segments A to D.\n50 to 70 words, written like the humans in that thread: agree first where natural, then add one verified fact, its consequence and Shashi's view ('In my view', 'I think', 'I would add'). End with one short question where it can start a conversation.\nRead the full linked article or video first. No overlap with existing comments. Never against a regulator or government. No pitching, no proof points in public.\nOne comment per person per day; space comments about an hour apart. Log every comment in the Comment log.", "sort": 4}, {"kind": "strategy", "title": "Outreach sequence", "body": "1. Warm: two comments on the person's posts on different days.\n2. Connect: request with a note under 300 characters: one useful point for their job, then one question they can answer from judgement.\n3. First message 1 to 2 days after they accept: the next layer of the same topic, or the free resource if relevant.\n4. In conversation: let them ask what Antier does. Proof points only on request (approved list only).\n5. Call: offer 20 minutes once a conversation is running, tied to a specific operational problem.\nNo reply in 7 days: back to commenting. No chasing messages.", "sort": 5}, {"kind": "strategy", "title": "Daily quotas", "body": "Week 1 (setup, about 70%): 6 comments, 10 connection requests, 3 messages, 1 InMail.\nWeeks 2 to 4: 8 comments, 15 connection requests, 5 messages, 1 InMail (weekdays).\nEvery day: reply to every comment on Shashi's own posts.\nInMail: maximum 5 a week, only to top-tier people already warmed with two comments.", "sort": 6}, {"kind": "strategy", "title": "Fix in week 1", "body": "Stop the bulk connection requests (about 28 a day going to people outside our segments).\nWithdraw off-target pending requests older than two weeks (list prepared on Monday).\nAct on warm leads first: Kenneth O'Friel (Toku, inbound), Jimena Santillán (replied), Mike Bernard (mentioned Shashi), Craig Borysowich (in conversation).\nIgor Pesin: no more messages; comment again from week 2.\nScore LinkedIn's 15 daily prospect suggestions as fit or no fit all week. Keep using them only if 40% or more fit.", "sort": 7}, {"kind": "strategy", "title": "Who does what", "body": "Claude: research, all drafts, fact checks, weekly numbers.\nAlok: approves final drafts, posts comments and messages, logs results.\nShashi: takes calls; 15 minutes a day for anything that needs his voice.\nVideo: Kanishk.Rewires motion studio.", "sort": 8}, {"kind": "strategy", "title": "Guardrails", "body": "Every number verified at a primary source. No invented experience, clients or anecdotes.\nApproved proof only (messages, on request): since 2011; 11+ tokenisation platforms; USD 3bn+ assets incl. a USD 2.5bn hub; FinCEN-registered remittance client, 38 seconds, 1.2% fee.\nNo em dashes, no banned words, no contractions. Pass anti-ai (reader mode), the kill list and humanizer before anything goes out.\nNothing is posted or sent without Alok's approval.", "sort": 9}, {"kind": "strategy", "title": "Weekly review (every Friday)", "body": "1. Enter the week's actuals in Results.\n2. Run the 10 AI citation questions in four tools and tick the AI citations tab.\n3. Look at the Comment log: which segments and angles earned replies.\n4. Move prospects forward in the pipeline; add 20 new ones.\n5. Adjust next week's board: double what worked, drop what did not.", "sort": 10}]}$j$;
begin
  select id into ws from workspaces where name ilike 'shashi%' order by created_at limit 1;
  if ws is null then raise exception 'No Shashi workspace found'; end if;
  update workspaces set start_date = '2026-11-09', quotas = '{"comment":6,"request":10,"dm":3,"inmail":1,"reply":1}' where id = ws;
  insert into prospects(workspace_id,name,role,company,segment,region,stage,warmth,next_action,next_date,linkedin,why,notes)
    select ws,name,role,company,segment,region,stage,warmth,next_action,next_date,linkedin,why,notes from jsonb_to_recordset(d->'p') as x(name text,role text,company text,segment text,region text,stage text,warmth text,next_action text,next_date date,linkedin text,why text,notes text);
  insert into posts(workspace_id,title,format,publish_date,status,topic,resource)
    select ws,title,format,publish_date,status,topic,resource from jsonb_to_recordset(d->'po') as x(title text,format text,publish_date date,status text,topic text,resource text);
  insert into templates(workspace_id,name,kind,body,sort) select ws,name,kind,body,sort from jsonb_to_recordset(d->'t') as x(name text,kind text,body text,sort int);
  insert into citation_questions(workspace_id,question,topic,region,sort) select ws,question,topic,region,sort from jsonb_to_recordset(d->'q') as x(question text,topic text,region text,sort int);
  insert into notes(workspace_id,kind,title,body,sort) select ws,kind,title,body,sort from jsonb_to_recordset(d->'s') as x(kind text,title text,body text,sort int);
end $do$;
select (select count(*) from prospects) prospects,(select count(*) from posts) posts,(select count(*) from templates) templates,(select count(*) from citation_questions) questions,(select count(*) from notes) notes;